################ FUNÇÕES
def base64_to_image(base64_string): ###CONVERTE BASE64 PARA BYTES DE IMAGEM string -> bytes
    if "data:image" in base64_string:
        base64_string = base64_string.split(",")[1]
    image_bytes = base64.b64decode(base64_string)
    return image_bytes
